package com.bank.payments.adapters.out.jdbc;

import com.bank.payments.domain.model.Account;
import com.bank.payments.domain.port.AccountRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.math.BigDecimal;
import java.util.Optional;

/** JDBC adapter of the port AccountRepository (legacy file CUENTAS). */
@Repository
public class JdbcAccountRepository implements AccountRepository {

    private final JdbcTemplate jdbcTemplate;

    public JdbcAccountRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    @Override
    public Optional<Account> findByNumber(Long accountNumber) {
        // READ for update: the row is locked inside the transaction of the use case.
        return jdbcTemplate.query(
                "SELECT account_number, account_type, balance, status "
                        + "FROM accounts WHERE account_number = ? FOR UPDATE",
                (rs, rowNum) -> new Account(
                        rs.getLong("account_number"),
                        rs.getString("account_type"),
                        rs.getBigDecimal("balance"),
                        rs.getString("status")),
                accountNumber).stream().findFirst();
    }

    @Override
    public void updateBalance(Long accountNumber, BigDecimal balance) {
        jdbcTemplate.update(
                "UPDATE accounts SET balance = ? WHERE account_number = ?",
                balance, accountNumber);
    }
}
